(()=>{const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];const messages={value:["ReSolve™ across your organisation","Reduce material demand. Build value across your organisation.","Connect analytical integrity, laboratory capacity, cost, supply resilience and circularity in one evidence-led business case.",["Shared value","Clear measures","One business case"]],"supply-chain":["ReSolve™ for Supply Chain","Help insulate your labs against solvent price volatility and supply disruption.","Reduce reliance on fresh solvent to limit exposure to price increases, make existing stocks last longer and support testing continuity when deliveries become less predictable.",["Price exposure","Supply continuity","Stock coverage"]],reports:["ReSolve™ client scenario reports","Client Scenario Reports","Explore four evaluation reports, including the independent SETU study and anonymised client records.",["Summary report","Audit trails","Chromatogram"]],quality:['ReSolve™ for Quality & Lab Operations','Maintain your analytical standards while reducing fresh mobile-phase preparation.','Evaluate the change against your existing method requirements: compare fresh and recycled mobile-phase results, then review the supporting records.',['Fresh versus recycled','Method-specific evidence','Recorded operation']],sustainability:['ReSolve™ for Sustainability & EHS','Reduce hazardous waste and CO₂ emissions. Capture the metrics across your labs.','Recycle prepared mobile phase within isocratic HPLC workflows, with a clear evidence trail from laboratory activity to waste, cost and estimated carbon prevention.',['Hazardous waste prevented','Reduced handling','Estimated CO₂e prevented']],procurement:['ReSolve™ for Procurement','Reduce lab solvent costs by 80%+ whilst lowering Scope 3 emissions.','Assess changes in prepared mobile-phase demand, material spend and supply requirements using verified operating data.',['Purchasing demand','Material cost avoided','Supply and contract fit']],research:['ReSolve™ research & evidence','Analytical results. Recorded recycling. Supporting evidence.','Study findings, chromatographic comparisons and instrument records from evaluated isocratic HPLC workflows.',['Method evidence','Instrument records','Traceability']],across:['Model Your Own Scenario','Turn measured prevention into a business case.','Start with prepared mobile-phase material cost avoided; assess capacity, handling and wider benefits alongside the full cost of adoption.',['Material cost','Operating value','Investment review']]};function activate(tab){if(!tab)return;qa('.view-tabs [role=tab]').forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});qa('.view-panel').forEach(p=>p.hidden=p.id!==tab.getAttribute('aria-controls'));const m=messages[tab.id.replace('nav-','')];q('#hero-perspective').textContent=m[0];q('#hero-title').textContent=m[1];{const title=q('#hero-title'),label=q('#hero-perspective'),hero=q('#persona-hero');let wrap=q('#quality-heading-wrap');if(tab.id==='nav-quality'){if(!wrap){wrap=document.createElement('div');wrap.id='quality-heading-wrap';hero.prepend(wrap);}wrap.append(label,title);title.innerHTML='Maintain your analytical standards while reducing fresh mobile-phase preparation.';}else if(wrap){const body=hero.querySelector('div:not(#quality-heading-wrap)');body.prepend(label);label.after(title);wrap.remove();}}q('#hero-summary').textContent=m[2];q('#hero-enquiry').textContent=tab.id==='nav-supply-chain'?'Discuss supply-chain requirements':'Discuss your methods';{let note=q('#procurement-headline-note');if(tab.id==='nav-procurement'){if(!note){note=document.createElement('p');note.id='procurement-headline-note';note.className='small';q('#hero-title').after(note);}note.textContent='Example opportunity—subject to validation at each site. The fixed example uses an 80% reduction assumption; 80%+ is not a measured purchasing result. Associated carbon estimates use supplied factors pending verification.';}else{note?.remove();}}q('#hero-values').innerHTML=m[3].map(x=>'<li>'+x+'</li>').join('');history.replaceState(null,'','#'+tab.getAttribute('aria-controls'));}qa('.view-tabs [role=tab]').forEach((t,i,a)=>{t.onclick=()=>activate(t);t.onkeydown=e=>{let j=e.key==='ArrowRight'?(i+1)%a.length:e.key==='ArrowLeft'?(i-1+a.length)%a.length:e.key==='Home'?0:e.key==='End'?a.length-1:null;if(j!==null){e.preventDefault();activate(a[j]);a[j].focus()}}});qa('[data-go]').forEach(b=>b.onclick=()=>{activate(q('#nav-'+b.dataset.go));q('#persona-hero').scrollIntoView()});activate(qa('.view-tabs [role=tab]').find(t=>'#'+t.getAttribute('aria-controls')===location.hash)||q('#nav-quality'));const systems=1;const years=3;const fmt=(v,d=0)=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:d}).format(v),money=v=>'€'+fmt(v),production=1,disposal=1;const set=(s,v)=>qa(s).forEach(x=>x.textContent=v);function bars(id,annual,format,stack=false){q(id).innerHTML=Array.from({length:years},(_,i)=>i+1).map(y=>'<div class="bar-col"><span class="bar-value">'+format(annual*y)+'</span><div class="bar-shape" style="height:'+(annual>0?y/years*136:0)+'px">'+(stack?'<i style="height:'+(100*window.resolveStudyModel().disposalShare)+'%"></i>':'')+'</div><span class="bar-year">Y'+y+'</span></div>').join('');q(id).setAttribute('role','img');q(id).setAttribute('aria-label',Array.from({length:years},(_,i)=>i+1).map(y=>'Year '+y+': '+format(annual*y)).join('; '))}function update(){const example={'calc-labs':1,'calc-hplc-count':10,'calc-flow':1,'calc-hours-day':16,'calc-days-week':5,'calc-weeks-year':48,'calc-solvent-cost':100,'calc-waste-reduction':80,'calc-recovery':80};const read=id=>example[id]||0;const systems=Math.floor(read('calc-labs')),annual=systems*Math.floor(read('calc-hplc-count'))*read('calc-flow')*60*read('calc-hours-day')*read('calc-days-week')*read('calc-weeks-year')/1000;const price=read('calc-solvent-cost'),waste=annual*read('calc-waste-reduction')/100,fresh=annual*read('calc-recovery')/100,cost=fresh*price,carbon=fresh*window.resolveStudyModel().production+waste*window.resolveStudyModel().disposal;set('[data-waste]',fmt(waste,1));set('[data-cost]',money(cost));set('[data-carbon]',fmt(carbon));set('[data-total-waste]',fmt(waste*years,1)+' L · ≈ '+fmt(waste*years/1000,2)+' tonnes');set('[data-total-cost]',money(cost*years));set('[data-total-carbon]',fmt(carbon*years/1000,2)+' tonnes');set('[data-systems]',systems);set('[data-plural]',systems===1?'':'s');bars('#waste-bars',waste,x=>fmt(x,1)+' L · ≈ '+fmt(x/1000,2)+' t');bars('#cost-bars',cost,money);bars('#carbon-bars',carbon,x=>fmt(x/1000,2)+' t',true);qa('[data-lab-view]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.labView)===systems)));set('[data-period]','three years')}qa('[data-lab-view]').forEach(b=>b.onclick=()=>{q('#calc-labs').value=b.dataset.labView;q('#calc-labs').dispatchEvent(new Event('input',{bubbles:true}));});document.addEventListener('resolve-model',update);update();qa('[data-enquiry]').forEach(b=>b.onclick=()=>q('#mock-dialog').showModal());q('#close-mock').onclick=()=>q('#mock-dialog').close();})();
(()=>{const $=id=>document.getElementById(id);const defaults={'calc-disposal-cost':10,'calc-labs':1,'calc-hplc-count':10,'calc-flow':1.2,'calc-hours-day':12,'calc-days-week':5,'calc-weeks-year':48,'calc-solvent-cost':90,'calc-water-cost':24,'calc-water-production':'','calc-methanol-production':'','calc-disposal-factor':1.57,'calc-recovery':80,'calc-waste-reduction':80,'calc-solvent-share':45,'calc-methanol-share':15};const limits={'calc-disposal-cost':1000000,'calc-labs':10000,'calc-hplc-count':100,'calc-flow':1000,'calc-hours-day':24,'calc-days-week':7,'calc-weeks-year':52,'calc-solvent-cost':1000000,'calc-water-cost':1000000,'calc-water-production':1000000,'calc-methanol-production':1000000,'calc-disposal-factor':1000000,'calc-recovery':100,'calc-waste-reduction':100,'calc-solvent-share':100,'calc-methanol-share':100};const ids=Object.keys(defaults);const qty=(v,d=0)=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:d}).format(v),eur=v=>'€'+qty(v);const num=id=>{const v=Number($(id).value);return Number.isFinite(v)?Math.min(limits[id],Math.max(0,v)):0};const set=(s,v)=>document.querySelectorAll(s).forEach(x=>x.textContent=v);function calc(){const mixture=window.resolveStudyModel();$('calc-solvent-share').value=mixture.acnPercent;$('calc-methanol-share').value=mixture.methanolPercent;$('calc-buffer-share').textContent=qty(mixture.bufferPercent,2);const labs=Math.floor(num('calc-labs')),perLab=Math.floor(num('calc-hplc-count')),systems=labs*perLab,annual=systems*num('calc-flow')*60*num('calc-hours-day')*num('calc-days-week')*num('calc-weeks-year')/1000,reduction=num('calc-recovery'),avoided=annual*reduction/100,saving=avoided*num('calc-solvent-cost');$('calc-volume').value=(annual/12).toFixed(2);$('calc-recovery-value').value=qty(reduction,4)+'%';$('calc-annual-saving').textContent=eur(saving);$('calc-solvent-baseline').textContent=eur(annual*num('calc-solvent-cost'));$('calc-annual-litres').textContent=qty(avoided,1)+' L / year';$('calc-recovery-impact').textContent='Assumed fresh mobile-phase demand prevented: '+qty(avoided,1)+' L/year across '+qty(labs)+(labs===1?' lab.':' labs.');$('calc-status').textContent='result for '+qty(labs)+(labs===1?' lab × ':' labs × ')+qty(perLab)+' HPLCs per lab = '+qty(systems)+' HPLCs. Same operating schedule and eligible workload per HPLC assumed.';$('bc-total-systems').textContent=qty(systems);$('bc-baseline-litres').textContent=qty(annual,1)+' L / year';set('[data-bc-volume]',qty(avoided,1)+' L');set('[data-bc-saving]',eur(saving));set('[data-bc-labs]',qty(labs));set('[data-bc-solvent]',qty(avoided*window.resolveStudyModel().organicFraction,1)+' L');set('[data-bc-carbon]',qty((avoided*window.resolveStudyModel().production+annual*num('calc-waste-reduction')/100*window.resolveStudyModel().disposal)/1000,2)+' tonnes CO₂e');document.dispatchEvent(new Event('resolve-model'));$('matrix-scope').textContent='Based on your inputs: '+qty(labs)+(labs===1?' lab · ':' labs · ')+qty(perLab)+' HPLCs per lab · '+qty(reduction,4)+'% net fresh reduction / '+qty(num('calc-waste-reduction'),2)+'% net waste reduction · '+eur(num('calc-solvent-cost'))+'/L.';}ids.forEach(id=>{$(id).addEventListener('input',calc);$(id).addEventListener('change',()=>{let n=num(id);if(id==='calc-labs'||id==='calc-hplc-count')n=Math.floor(n);$(id).value=n;calc()})});$('calc-reset').onclick=()=>{ids.forEach(id=>$(id).value=defaults[id]);calc()};calc();})();
(()=>{const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],f=(v,d=0)=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:d}).format(v);function render(){const n=id=>Math.max(0,Number(q('#'+id).value)||0),labs=Math.floor(n('calc-labs')),hplc=Math.floor(n('calc-hplc-count')),base=labs*hplc*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000,rate=n('calc-recovery'),share=n('calc-solvent-share'),price=n('calc-solvent-cost'),litres=base*rate/100,wasteLitres=base*n('calc-waste-reduction')/100,cost=litres*price,carbon=(litres*window.resolveStudyModel().production+wasteLitres*window.resolveStudyModel().disposal)/1000;const summary=f(labs)+' lab'+(labs===1?'':'s')+' · '+f(hplc)+' HPLCs per lab · '+f(n('calc-flow'),2)+' mL/min per HPLC · '+f(n('calc-hours-day'),1)+' hours/day · '+f(n('calc-days-week'),1)+' days/week · '+f(n('calc-weeks-year'),1)+' weeks/year';q('.sample-band strong').textContent=f(labs)+' lab'+(labs===1?'':'s')+' · cumulative impact over 3 years';q('.sample-band small').textContent=f(hplc)+' HPLCs per lab · '+f(share,1)+'% ACN / '+f(window.resolveStudyModel().methanolPercent,1)+'% methanol / '+f(window.resolveStudyModel().bufferPercent,1)+'% buffer · '+f(rate,4)+'% net fresh reduction / '+f(n('calc-waste-reduction'),2)+'% net waste reduction · €'+f(price,2)+'/L prepared mobile phase';all('[data-model-basis]').forEach(e=>e.textContent='Based on '+summary+' · '+f(rate,4)+'% net fresh reduction / '+f(n('calc-waste-reduction'),2)+'% net waste reduction · €'+f(price,2)+'/L of the whole prepared mobile phase.');all('[data-model-rate]').forEach(e=>e.textContent=f(rate,1)+'%');q('#cumulative-context').textContent=summary+'. Same workload, recycling rate and unit cost each year; no inflation or discounting.';[['cost',cost+wasteLitres*n('calc-disposal-cost'),v=>'€'+f(v)],['waste',wasteLitres,v=>f(v,1)+' L · ≈ '+f(v/1000,2)+' t'],['carbon',carbon,v=>f(v,2)+' t CO₂e']].forEach(([key,value,format])=>{const el=q('#cumulative-'+key);el.innerHTML=Array.from({length:window.resolveProjectionYears||3},(_,i)=>i+1).map(y=>'<div class="cum-col"><strong>'+format(value*y)+'</strong><div class="cum-track"><div class="cum-bar" style="height:'+(value?y/(window.resolveProjectionYears||3)*100:0)+'%"></div></div><span>'+y+(y===1?' year':' years')+'</span></div>').join('');el.setAttribute('aria-label',Array.from({length:window.resolveProjectionYears||3},(_,i)=>i+1).map(y=>y+' years: '+format(value*y)).join('; '));});}document.addEventListener('resolve-model',render);render();})();
(()=>{const form=document.getElementById('resolvePilotForm'),dialog=document.getElementById('mock-dialog'),status=document.getElementById('pilotFormStatus'),submit=form.querySelector('[type=submit]');document.querySelectorAll('[data-enquiry]').forEach(button=>{button.onclick=()=>{document.getElementById('pilotPerspective').value=document.querySelector('[role=tab][aria-selected=true]')?.textContent.trim()||'General enquiry';document.getElementById('enquiryCta').value=button.textContent.trim();if(!submit.disabled){status.textContent='';status.className='pilot-form-status';}dialog.showModal();};});form.addEventListener('submit',async event=>{event.preventDefault();if(submit.disabled||!form.reportValidity())return;submit.disabled=true;submit.textContent='Sending…';status.className='pilot-form-status';status.textContent='Sending your enquiry…';try{const response=await fetch(form.action,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const data=await response.json();if(!response.ok||data.success!==true)throw Error('Submission failed');form.reset();status.className='pilot-form-status success';status.textContent='Thank you. Your enquiry has been sent to Antech.';}catch{status.className='pilot-form-status error';status.textContent='We could not send your enquiry. Please try again, or email info@antech.ie.';}finally{submit.disabled=false;submit.textContent='Send enquiry';}});})();